2	 * Autonomous reviewer dispatch.
3	 *
4	 * Triggered when a task's status is `in_review`. The orchestrator calls
5	 * `dispatchReviewer` to:
6	 *
7	 *   1. Claim the review cycle by appending a `reviewer_started` log entry to
8	 *      the task YAML on the management-repo feature branch and pushing.
9	 *      First-push-wins: if the push is rejected, another agent claimed first.
10	 *
11	 *   2. Build a reviewer briefing that instructs Claude to execute /review-pr.
12	 *
13	 *   3. Submit the reviewer executor with kind="review" so the reap loop routes
14	 *      its completion to dispatchReviewResult (T5/T6) rather than
15	 *      dispatchExecutorResult.
16	 *
17	 * The reviewer writes result.json with:
18	 *   { terminal_status: "passed" | "change_requested" | "escalate", ... }
19	 */
20	
21	import { execSync, spawnSync } from "node:child_process";
22	import { join } from "node:path";
23	import { tmpdir } from "node:os";
24	import { randomUUID } from "node:crypto";
25	import type { Task } from "../types/task.js";
26	import { buildGitEnv } from "../git-env.js";
27	import { SubProcessAdapter } from "../adapters/executor/subprocess.js";
28	import type { ExecutorPortInput, CompletionBrokerPort } from "@workflow/runtime-abi";
29	import { taskYamlRelPath } from "../paths.js";
30	import { readTask, writeTask } from "../utils/task-yaml-io.js";
31	import { writeBriefing } from "../briefing/write-briefing.js";
32	import { generateReviewerBriefing } from "../briefing/reviewer-briefing.js";
33	
34	// ── Public types ──────────────────────────────────────────────────────────────
35	
36	export type ReviewerDispatchOutcome =
37	  | "claim_lost"
38	  | "dispatched";
39	
40	export interface DispatchReviewerOptions {
41	  workspaceRoot: string;
42	  featureId: string;
43	  taskId: string;
44	  taskBranch: string;
45	  implRepoRoot: string;
46	  /** SSH or HTTPS URL of the implementation repo. */
47	  implRepoUrl: string;
48	  gitAuthorEmail: string;
49	  gitAuthorName?: string;
50	  sshKeyPath?: string;
51	  workflowLocalPath: string;
52	  maxTurns: number;
53	  maxTokens: number;
54	  logSinkEnabled: boolean;
55	  reviewerModel: string;
56	  workspaceId: string;
57	  githubToken: string;
58	  /** Max review cycles before escalating. Default: 3. */
59	  maxReviewCycles?: number;
60	  /** Completion broker for async submit. */
61	  broker: CompletionBrokerPort;
62	  /** Callback URL the runner wrapper will POST to. Pre-computed by caller. */
63	  callbackUrl: string;
64	  emit: (event: Record<string, unknown>) => void;
65	}
66	
67	// ── Internal helpers ──────────────────────────────────────────────────────────
68	
69	/** Count in_review log entries — used to enforce the cycle limit. */
70	function countReviewCycles(task: Task): number {
71	  return task.log.filter((e) => e.action === "reviewer_started").length;
72	}
73	
74	// ── Public API ────────────────────────────────────────────────────────────────
75	
76	/**
77	 * Claim and dispatch a reviewer executor for a task in `in_review` status.
78	 *
79	 * Returns "claim_lost" when another agent already claimed this review cycle,
80	 * or "dispatched" when the reviewer was successfully submitted.
81	 */
82	export async function dispatchReviewer(
83	  opts: DispatchReviewerOptions,
84	): Promise<ReviewerDispatchOutcome> {
85	  const {
86	    workspaceRoot,
87	    featureId,
88	    taskId,
89	    taskBranch,
90	    implRepoRoot,
91	    implRepoUrl,
92	    gitAuthorEmail,
93	    gitAuthorName = gitAuthorEmail,
94	    sshKeyPath,
95	    workflowLocalPath,
96	    maxTurns,
97	    maxTokens,
98	    logSinkEnabled,
99	    reviewerModel,
100	    workspaceId,
101	    githubToken,
102	    maxReviewCycles = 3,
103	    broker,
104	    callbackUrl,
105	    emit,
106	  } = opts;
107	
108	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
109	
110	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
111	  try {
112	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
113	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
114	    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
115	  } catch (e) {
116	    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
117	    return "claim_lost";
118	  }
119	
120	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
121	  let task: Task;
122	  try {
123	    task = readTask(workspaceRoot, featureId, taskId);
124	  } catch (e) {
125	    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
126	    return "claim_lost";
127	  }
128	
129	  if (task.status !== "in_review") {
130	    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: `task status is ${task.status}, expected in_review` });
131	    return "claim_lost";
132	  }
133	
134	  // Duplicate-claim guard: if the last log action is already `reviewer_started`,
135	  // another orchestrator instance claimed this cycle first.
136	  const lastEntry = task.log[task.log.length - 1];
137	  if (lastEntry?.action === "reviewer_started") {
138	    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is reviewer_started — already claimed" });
139	    return "claim_lost";
140	  }
141	
142	  const reviewCycleCount = countReviewCycles(task);
143	
144	  // ── 3. Write reviewer_started log entry and push (first-push-wins) ───────────
145	  const now = new Date().toISOString();
146	  task.log.push({
147	    action: "reviewer_started",
148	    by: gitAuthorEmail,
149	    at: now,
150	    note: `Reviewer dispatch claimed (cycle ${reviewCycleCount + 1} of ${maxReviewCycles}).`,
151	  });
152	  task.execution.last_updated_by = gitAuthorEmail;
153	  task.execution.last_updated_at = now;
154	  writeTask(workspaceRoot, featureId, task);
155	
156	  const relPath = taskYamlRelPath(featureId, taskId);
157	  try {
158	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
159	    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): reviewer_started — claim cycle ${reviewCycleCount + 1}"`, { env, stdio: "pipe" });
160	  } catch (e) {
161	    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
162	    return "claim_lost";
163	  }
164	
165	  let claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
166	    env, encoding: "utf-8",
167	  });
168	
169	  if (claimPush.status !== 0) {
170	    // Push rejected — rebase onto origin and re-check duplicate-claim guard.
171	    try {
172	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
173	      execSync(`git -C "${workspaceRoot}" rebase origin/${taskBranch}`, { env, stdio: "pipe" });
174	    } catch (e) {
175	      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: `rebase failed after push rejection: ${String(e)}` });
176	      return "claim_lost";
177	    }
178	
179	    const rebasedTask = readTask(workspaceRoot, featureId, taskId);
180	    if (rebasedTask.status !== "in_review") {
181	      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: `task status changed to ${rebasedTask.status} during rebase` });
182	      return "claim_lost";
183	    }
184	    const rebasedLast = rebasedTask.log[rebasedTask.log.length - 1];
185	    if (rebasedLast?.action === "reviewer_started") {
186	      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: "another agent claimed during rebase" });
187	      return "claim_lost";
188	    }
189	
190	    claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
191	      env, encoding: "utf-8",
192	    });
193	    if (claimPush.status !== 0) {
194	      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
195	      return "claim_lost";
196	    }
197	  }
198	
199	  emit({ type: "reviewer_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr?.url, cycle: reviewCycleCount + 1 });
200	
201	  // ── 4. Build reviewer briefing and submit executor (kind=review) ──────────────
202	  const resultPath = join(tmpdir(), `reviewer-result-${taskId}.json`);
203	
204	  const reviewerBriefing = generateReviewerBriefing({
205	    taskId,
206	    featureId,
207	    taskTitle: task.title,
208	    taskBranch,
209	    taskRepo: task.repo,
210	    taskRepoRoot: implRepoRoot,
211	    workspaceRoot,
212	    prUrl: task.pr?.url ?? "",
213	    gitAuthorEmail,
214	    gitAuthorName,
215	    reviewerModel,
216	    resultPath,
217	    reviewCycleCount,
218	    maxReviewCycles,
219	  });
220	
221	  const { briefingPath } = writeBriefing({ taskId: `reviewer-${taskId}`, briefingContent: reviewerBriefing });
222	  const nonce = randomUUID();
223	
224	  const input: ExecutorPortInput = {
225	    taskId,
226	    featureId,
227	    workspaceId,
228	    taskRepoUrl: implRepoUrl,
229	    taskRepoBranch: taskBranch,
230	    taskRepoPath: implRepoRoot,
231	    briefingPath,
232	    resultPath,
233	    budgetTokens: maxTokens,
234	    implementationModel: reviewerModel,
235	    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
236	    githubToken,
237	    callbackUrl,
238	    nonce,
239	  };
240	
241	  const reviewerAdapter = new SubProcessAdapter({
242	    broker,
243	    handleKind: "review",
244	    extraEnv: {
245	      WORKSPACE_ROOT: workspaceRoot,
246	      TASK_BRANCH: taskBranch,
247	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
248	      GIT_AUTHOR_NAME: gitAuthorName,
249	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
250	      MAX_TURNS: String(maxTurns),
251	      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
252	      MAX_REVIEW_CYCLES: String(maxReviewCycles),
253	      GITHUB_TOKEN: githubToken,
254	    },
255	  });
256	
257	  const handle = await reviewerAdapter.submit(input);
258	
259	  emit({
260	    type: "reviewer_submitted",
261	    task_id: taskId,
262	    feature_id: featureId,
263	    handle,
264	    cycle: reviewCycleCount + 1,
265	  });
266	
267	  return "dispatched";
268	}
