1	/**
2	 * SubProcessAdapter — ExecutorPort adapter (Wave 3 / T5).
3	 *
4	 * Wave 3 version implements the async runner-callback shape:
5	 *  - submit() registers the handle with the broker, then spawns the runner
6	 *    wrapper (T4) as a detached child. Returns the handle immediately without
7	 *    waiting for the executor to finish.
8	 *  - Completion arrives via HTTP callback: runner POSTs { handle, nonce, result }
9	 *    to the broker's /callback endpoint; the orchestrator drains via
10	 *    broker.listCompleted (T6).
11	 *  - readResult() is a no-op for this profile — result rides in the callback.
12	 *  - ack() removes the handle from the supervision map, cleans up the result
13	 *    file, and delegates to broker.ack.
14	 *
15	 * Runner-supervision map:
16	 *   Keyed by handle; stores (pid, startedAt, nonce, callbackUrl, resultPath).
17	 *   Purpose: the wrapper-crash safety net only — not in-flight state (the
18	 *   broker owns that). On child.on('exit'), a grace timer fires; if the
19	 *   handle is still in the supervision map when the timer fires, the adapter
20	 *   POSTs a synthetic "failed" completion to the broker on the runner's behalf.
21	 */
22	
23	import { randomUUID } from "node:crypto";
24	import { spawn } from "node:child_process";
25	import { unlinkSync } from "node:fs";
26	import * as http from "node:http";
27	import * as https from "node:https";
28	import { join } from "node:path";
29	import type {
30	  ExecutorPort,
31	  ExecutorPortInput,
32	  ExecutorHandle,
33	  ExecutorResult,
34	  CompletionBrokerPort,
35	} from "@workflow/runtime-abi";
36	
37	// ── Types ─────────────────────────────────────────────────────────────────────
38	
39	export interface SubProcessAdapterOpts {
40	  /**
41	   * Path to runner.js (the platform-owned wrapper script from T4).
42	   * Defaults to the standard location baked into the container image.
43	   */
44	  runnerBinPath?: string;
45	
46	  /**
47	   * Path to the executor binary. Passed as EXECUTOR_BIN env var to the
48	   * runner wrapper so it knows what to exec. Defaults to the standard
49	   * container location; override in tests.
50	   */
51	  executorBinPath?: string;
52	
53	  /**
54	   * Maximum wall-clock milliseconds before the watchdog kills the runner.
55	   * Defaults to 2 hours (7_200_000 ms).
56	   */
57	  timeoutMs?: number;
58	
59	  /**
60	   * Extra environment variables passed to the runner wrapper (and inherited
61	   * by the executor). Used for day-1 single-container extras like
62	   * WORKSPACE_ROOT, GIT_AUTHOR_EMAIL, WORKFLOW_LOCAL_PATH, etc.
63	   */
64	  extraEnv?: NodeJS.ProcessEnv;
65	
66	  /**
67	   * CompletionBrokerPort instance. Required for the full async callback flow.
68	   * If absent, broker.register is skipped and the adapter operates in
69	   * broker-less mode (useful for isolated unit tests).
70	   */
71	  broker?: CompletionBrokerPort;
72	
73	  /**
74	   * Grace window (ms) after child.on('exit') before the safety-net synthetic
75	   * failure is posted to the broker. This allows a callback that was in-flight
76	   * at crash time to arrive before we synthesize a failure.
77	   * Default: 5 000 ms.
78	   */
79	  crashGraceMs?: number;
80	}
81	
82	interface SupervisionEntry {
83	  pid: number;
84	  startedAt: string; // ISO 8601
85	  nonce: string;
86	  callbackUrl: string;
87	  resultPath: string;
88	  taskId: string;
89	  featureId: string;
90	}
91	
92	// ── Defaults ──────────────────────────────────────────────────────────────────
93	
94	const DEFAULT_RUNNER_BIN = join(
95	  process.env.EXECUTOR_BIN_PREFIX ?? "/workflow",
96	  "runtime",
97	  "runner-wrapper",
98	  "runner.js",
99	);
100	
101	const DEFAULT_TIMEOUT_MS = 7_200_000;
102	const DEFAULT_CRASH_GRACE_MS = 5_000;
103	
104	// ── Helpers ───────────────────────────────────────────────────────────────────
105	
106	function emit(event: Record<string, unknown>): void {
107	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
108	}
109	
110	/** HTTP POST for the safety-net synthetic failure. Resolves regardless of status. */
111	function _httpPost(url: string, body: string): Promise<void> {
112	  return new Promise((resolve, reject) => {
113	    let u: URL;
114	    try {
115	      u = new URL(url);
116	    } catch {
117	      reject(new Error(`_httpPost: invalid URL: ${url}`));
118	      return;
119	    }
120	    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
121	    const req = lib.request(
122	      {
123	        hostname: u.hostname,
124	        port: u.port || (u.protocol === "https:" ? 443 : 80),
125	        path: u.pathname + u.search,
126	        method: "POST",
127	        headers: {
128	          "Content-Type": "application/json",
129	          "Content-Length": Buffer.byteLength(body),
130	        },
131	      },
132	      (res) => {
133	        res.resume(); // drain the response
134	        resolve();
135	      },
136	    );
137	    req.on("error", reject);
138	    req.write(body);
139	    req.end();
140	  });
141	}
142	
143	// ── SubProcessAdapter ─────────────────────────────────────────────────────────
144	
145	export class SubProcessAdapter implements ExecutorPort {
146	  private readonly runnerBinPath: string;
147	  private readonly executorBinPath: string | undefined;
148	  private readonly timeoutMs: number;
149	  private readonly extraEnv: NodeJS.ProcessEnv;
150	  private readonly broker: CompletionBrokerPort | null;
151	  private readonly crashGraceMs: number;
152	
153	  /** Keyed by handle; tracks in-flight runners for the safety-net sweep. */
154	  private readonly supervision = new Map<ExecutorHandle, SupervisionEntry>();
155	
156	  constructor(opts: SubProcessAdapterOpts = {}) {
157	    this.runnerBinPath = opts.runnerBinPath ?? DEFAULT_RUNNER_BIN;
158	    this.executorBinPath = opts.executorBinPath;
159	    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
160	    this.extraEnv = opts.extraEnv ?? {};
161	    this.broker = opts.broker ?? null;
162	    this.crashGraceMs = opts.crashGraceMs ?? DEFAULT_CRASH_GRACE_MS;
163	  }
164	
165	  // ── ExecutorPort ─────────────────────────────────────────────────────────
166	
167	  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
168	    const {
169	      taskId,
170	      featureId,
171	      workspaceId,
172	      taskRepoUrl,
173	      taskRepoBranch,
174	      taskRepoPath,
175	      briefingPath,
176	      resultPath,
177	      budgetTokens,
178	      implementationModel,
179	      sshPrivateKey,
180	      githubToken,
181	      callbackUrl,
182	      nonce,
183	    } = input;
184	
185	    const handle = randomUUID();
186	    const startedAt = new Date().toISOString();
187	
188	    // 1. Register handle with broker before spawning (broker must record it
189	    //    before the runner can POST back, else the callback arrives at an
190	    //    unregistered handle and is rejected 401).
191	    if (this.broker) {
192	      await this.broker.register(handle, nonce, {
193	        kind: "impl",
194	        task_id: taskId,
195	        feature_id: featureId,
196	        started_at: startedAt,
197	      });
198	    }
199	
200	    // 2. Build environment for the runner wrapper (and inherited by executor).
201	    const childEnv: NodeJS.ProcessEnv = {
202	      ...process.env,
203	      ...this.extraEnv,
204	      // Formal ABI env vars — passed through to the executor
205	      TASK_ID: taskId,
206	      FEATURE_ID: featureId,
207	      WORKSPACE_ID: workspaceId,
208	      TASK_REPO_URL: taskRepoUrl,
209	      TASK_REPO_BRANCH: taskRepoBranch,
210	      TASK_REPO_PATH: taskRepoPath,
211	      BRIEFING_PATH: briefingPath,
212	      RESULT_PATH: resultPath,
213	      GITHUB_TOKEN: githubToken,
214	      ...(sshPrivateKey ? { SSH_PRIVATE_KEY: sshPrivateKey } : {}),
215	      ...(budgetTokens !== undefined ? { BUDGET_TOKENS: String(budgetTokens) } : {}),
216	      ...(implementationModel ? { IMPLEMENTATION_MODEL: implementationModel } : {}),
217	      // Runner wrapper contract (T-Q10)
218	      CALLBACK_URL: callbackUrl,
219	      HANDLE: handle,
220	      NONCE: nonce,
221	      ...(this.executorBinPath ? { EXECUTOR_BIN: this.executorBinPath } : {}),
222	    };
223	
224	    emit({
225	      type: "executor_spawn",
226	      task_id: taskId,
227	      feature_id: featureId,
228	      handle,
229	      runner: this.runnerBinPath,
230	    });
231	
232	    // 3. Spawn runner wrapper — non-blocking; returns immediately.
233	    const child = spawn("node", [this.runnerBinPath], {
234	      env: childEnv,
235	      stdio: "inherit",
236	      detached: false,
237	    });
238	
239	    // 4. Track in supervision map.
240	    this.supervision.set(handle, {
241	      pid: child.pid ?? 0,
242	      startedAt,
243	      nonce,
244	      callbackUrl,
245	      resultPath,
246	      taskId,
247	      featureId,
248	    });
249	
250	    // 5. Watchdog: kill runner if it exceeds the wall-clock timeout.
251	    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
252	      watchdog = null;
253	      if (!child.killed) {
254	        emit({
255	          type: "executor_timeout",
256	          task_id: taskId,
257	          feature_id: featureId,
258	          handle,
259	          timeout_ms: this.timeoutMs,
260	        });
261	        child.kill("SIGTERM");
262	      }
263	    }, this.timeoutMs);
264	    // Don't hold the event loop open for the watchdog.
265	    if (watchdog.unref) watchdog.unref();
266	
267	    // 6. Safety net: if the runner exits without the broker receiving a
268	    //    callback within crashGraceMs, synthesize a "failed" completion.
269	    child.on("exit", (code, signal) => {
270	      if (watchdog !== null) {
271	        clearTimeout(watchdog);
272	        watchdog = null;
273	      }
274	
275	      emit({
276	        type: "executor_exit",
277	        task_id: taskId,
278	        feature_id: featureId,
279	        handle,
280	        exit_code: code,
281	        signal,
282	      });
283	
284	      // Exit code 0 means runner.js completed its postWithRetry successfully —
285	      // the broker already has the real result. Skip the safety net entirely.
286	      // The supervision entry stays so ack() can still clean up the result file.
287	      if (code === 0 && signal === null) {
288	        return;
289	      }
290	
291	      const graceTimer: ReturnType<typeof setTimeout> = setTimeout(() => {
292	        if (!this.supervision.has(handle)) return; // already acked
293	        const entry = this.supervision.get(handle)!;
294	        this.supervision.delete(handle);
295	
296	        if (!entry.callbackUrl) return; // no callback URL to POST to
297	
298	        const reason = signal
299	          ? `runner_killed_by_signal: ${signal}`
300	          : code !== null && code !== 0
301	            ? `runner_crashed (exit ${code})`
302	            : "runner_no_callback";
303	
304	        emit({
305	          type: "executor_safety_net",
306	          task_id: entry.taskId,
307	          feature_id: entry.featureId,
308	          handle,
309	          reason,
310	        });
311	
312	        const body = JSON.stringify({
313	          handle,
314	          nonce: entry.nonce,
315	          result: { terminal_status: "failed", blocked_reason: reason },
316	        });
317	
318	        _httpPost(entry.callbackUrl, body).catch(() => {
319	          // Best-effort — ignore POST failures in the safety net.
320	        });
321	      }, this.crashGraceMs);
322	
323	      // Don't hold the event loop open for the grace timer.
324	      if (graceTimer.unref) graceTimer.unref();
325	    });
326	
327	    return handle;
328	  }
329	
330	  /**
331	   * Wave 3: result arrives via broker callback — readResult is a no-op for
332	   * this profile. Returns a "failed / handle_not_found" tombstone so callers
333	   * that mistakenly poll readResult get a predictable signal.
334	   */
335	  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
336	    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
337	  }
338	
339	  // ── Supervision helpers ───────────────────────────────────────────────────
340	
341	  /**
342	   * Acknowledge a completed handle:
343	   *  - Removes the entry from the supervision map (disarms the safety net).
344	   *  - Deletes the temp result file written by the executor.
345	   *  - Delegates to broker.ack to commit consumption in the broker.
346	   *
347	   * Call this after the orchestrator has successfully processed the completion
348	   * returned by broker.listCompleted.
349	   */
350	  async ack(handle: ExecutorHandle): Promise<void> {
351	    const entry = this.supervision.get(handle);
352	    if (entry) {
353	      this.supervision.delete(handle);
354	      try {
355	        unlinkSync(entry.resultPath);
356	      } catch {
357	        // Best-effort — file may already be gone.
358	      }
359	    }
360	    if (this.broker) {
361	      await this.broker.ack(handle);
362	    }
363	  }
364	
365	  /** Number of handles currently tracked in the supervision map. */
366	  supervisionSize(): number {
367	    return this.supervision.size;
368	  }
369	}
