/**
 * Tests for briefing/reviewer-briefing.ts — generateReviewerBriefing.
 *
 * Test plan:
 *   1. All opts fields appear in the returned string in the appropriate sections.
 *   2. The string never contains the literal text "undefined" or "null".
 *   3. Required section headers are present.
 *   4. The briefing instructs the executor to invoke /review-pr.
 *   5. The cycle count and max review cycles are both present.
 *   6. The result path is referenced in the What you must do and Rules sections.
 *   7. All three terminal_status values are mentioned (passed, change_requested, escalate).
 *   8. The PR URL is included in the task context.
 *   9. Different reviewCycleCounts produce different output (cycle display changes).
 *  10. GITHUB_TOKEN is mentioned in the Rules section.
 *  11. Cycle escalation instruction is present when at the limit.
 *  12. The confidence threshold (CONFIDENCE_THRESHOLD) is referenced.
 */

import { describe, it, expect } from "vitest";
import {
  generateReviewerBriefing,
  type ReviewerBriefingOpts,
} from "../src/briefing/reviewer-briefing.js";

const BASE_OPTS: ReviewerBriefingOpts = {
  taskId: "T3",
  featureId: "autonomous-task-orchestrator",
  taskTitle: "review-pr skill",
  taskBranch: "feature/autonomous-task-orchestrator-T3",
  taskRepo: "workflow",
  taskRepoRoot: "/agent/data/agent-workflow",
  workspaceRoot: "/agent/data/project-workspace",
  prUrl: "https://github.com/tiendv89/agent-workflow/pull/93",
  gitAuthorEmail: "reviewer@example.com",
  gitAuthorName: "Reviewer Bot",
  reviewerModel: "claude-sonnet-4-6",
  resultPath: "/tmp/reviewer-result-T3.json",
  reviewCycleCount: 0,
  maxReviewCycles: 3,
};

describe("generateReviewerBriefing — returns a non-empty string", () => {
  it("returns a string", () => {
    const result = generateReviewerBriefing(BASE_OPTS);
    expect(typeof result).toBe("string");
    expect(result.length).toBeGreaterThan(0);
  });
});

// ── Section 1: opts fields appear in output ───────────────────────────────────

describe("generateReviewerBriefing — opts fields appear in output", () => {
  it("contains taskId", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.taskId);
  });

  it("contains featureId", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.featureId);
  });

  it("contains taskTitle", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.taskTitle);
  });

  it("contains taskBranch", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.taskBranch);
  });

  it("contains taskRepo", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.taskRepo);
  });

  it("contains taskRepoRoot", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.taskRepoRoot);
  });

  it("contains workspaceRoot", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.workspaceRoot);
  });

  it("contains prUrl", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.prUrl);
  });

  it("contains gitAuthorEmail", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.gitAuthorEmail);
  });

  it("contains gitAuthorName", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.gitAuthorName);
  });

  it("contains reviewerModel", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.reviewerModel);
  });

  it("contains resultPath", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain(BASE_OPTS.resultPath);
  });
});

// ── Section 2: no "undefined" or "null" ──────────────────────────────────────

describe("generateReviewerBriefing — no literal undefined or null", () => {
  it("does not contain the literal text 'undefined'", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).not.toContain("undefined");
  });

  it("does not contain the literal text 'null'", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).not.toContain("null");
  });
});

// ── Section 3: required section headers ───────────────────────────────────────

describe("generateReviewerBriefing — required section headers", () => {
  it("includes ## Identity section", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("## Identity");
  });

  it("includes ## Your claimed task section", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("## Your claimed task");
  });

  it("includes ## Reviewer context section", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("## Reviewer context");
  });

  it("includes ## What you must do section", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("## What you must do");
  });

  it("includes ## Model section", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("## Model");
  });

  it("includes ## Rules section", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("## Rules");
  });
});

// ── Section 4: instructs executor to invoke /review-pr ───────────────────────

describe("generateReviewerBriefing — instructs /review-pr", () => {
  it("contains '/review-pr' instruction", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("/review-pr");
  });

  it("places /review-pr after the What you must do heading", () => {
    const result = generateReviewerBriefing(BASE_OPTS);
    const mustDoIdx = result.indexOf("## What you must do");
    const reviewPrIdx = result.indexOf("/review-pr");
    expect(mustDoIdx).toBeGreaterThanOrEqual(0);
    expect(reviewPrIdx).toBeGreaterThan(mustDoIdx);
  });
});

// ── Section 5: cycle count and max review cycles ──────────────────────────────

describe("generateReviewerBriefing — cycle count and max cycles", () => {
  it("contains the max review cycles value", () => {
    const result = generateReviewerBriefing(BASE_OPTS);
    expect(result).toContain(String(BASE_OPTS.maxReviewCycles));
  });

  it("displays the human-readable cycle number (reviewCycleCount + 1)", () => {
    const result = generateReviewerBriefing(BASE_OPTS);
    // cycle 1 of 3 when reviewCycleCount=0
    expect(result).toContain(`${BASE_OPTS.reviewCycleCount + 1}`);
  });

  it("contains the MAX_REVIEW_CYCLES env var name", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("MAX_REVIEW_CYCLES");
  });

  it("different reviewCycleCounts produce different output", () => {
    const r1 = generateReviewerBriefing({ ...BASE_OPTS, reviewCycleCount: 0 });
    const r2 = generateReviewerBriefing({ ...BASE_OPTS, reviewCycleCount: 2 });
    expect(r1).not.toBe(r2);
  });

  it("shows cycle 1 of 3 for reviewCycleCount=0 maxReviewCycles=3", () => {
    const result = generateReviewerBriefing({ ...BASE_OPTS, reviewCycleCount: 0, maxReviewCycles: 3 });
    expect(result).toContain("1");
    expect(result).toContain("3");
  });

  it("shows cycle 2 of 3 for reviewCycleCount=1 maxReviewCycles=3", () => {
    const result = generateReviewerBriefing({ ...BASE_OPTS, reviewCycleCount: 1, maxReviewCycles: 3 });
    // The reviewer context section should show cycle 2 of 3
    const cycleIdx = result.indexOf("Reviewer context");
    const snippet = result.slice(cycleIdx, cycleIdx + 200);
    expect(snippet).toContain("2");
  });
});

// ── Section 6: result path placement ─────────────────────────────────────────

describe("generateReviewerBriefing — result path in output", () => {
  it("result path appears in the What you must do section", () => {
    const result = generateReviewerBriefing(BASE_OPTS);
    const mustDoIdx = result.indexOf("## What you must do");
    const rulesIdx = result.indexOf("## Rules");
    const pathIdx = result.indexOf(BASE_OPTS.resultPath);
    expect(pathIdx).toBeGreaterThan(mustDoIdx);
    expect(pathIdx).toBeLessThan(rulesIdx);
  });

  it("result path also appears in the Rules section", () => {
    const result = generateReviewerBriefing(BASE_OPTS);
    const rulesIdx = result.indexOf("## Rules");
    const lastPathIdx = result.lastIndexOf(BASE_OPTS.resultPath);
    expect(lastPathIdx).toBeGreaterThan(rulesIdx);
  });
});

// ── Section 7: terminal_status values ────────────────────────────────────────

describe("generateReviewerBriefing — terminal_status values", () => {
  it("mentions 'passed' terminal_status", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("passed");
  });

  it("mentions 'change_requested' terminal_status", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("change_requested");
  });

  it("mentions 'escalate' terminal_status", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("escalate");
  });

  it("mentions 'terminal_status' key", () => {
    expect(generateReviewerBriefing(BASE_OPTS)).toContain("terminal_status");
  });
});

// ── Section 8: PR URL in task context ────────────────────────────────────────

describe("generateReviewerBriefing — PR URL placement", () => {
  it("PR URL appears after the Your claimed task heading", () => {
    const result = generateReviewerBriefing(BASE_OPTS);
    const claimedIdx = result.indexOf("## Your claimed task");
    const prIdx = result.indexOf(BASE_OPTS.prUrl!);
    expect(claimedIdx).toBeGreaterThanOrEqual(0);
    expect(prIdx).toBeGreaterThan(claimedIdx);
  });
});

// ── Section 9: different taskIds produce different outputs ────────────────────

describe("generateReviewerBriefing — different inputs → different outputs", () => {
  it("different taskIds produce different outputs", () => {
    const r1 = generateReviewerBriefing(BASE_OPTS);
    const r2 = generateReviewerBriefing({ ...BASE_OPTS, taskId: "T99" });
    expect(r1).not.toBe(r2);
    expect(r2).toContain("T99");
  });

  it("different resultPaths produce different outputs", () => {
    const r1 = generateReviewerBriefing(BASE_OPTS);
    const r2 = generateReviewerBriefing({ ...BASE_OPTS, resultPath: "/tmp/other-result.json" });
    expect(r1).not.toBe(r2);
    expect(r2).toContain("/tmp/other-result.json");
  });

  it("different reviewerModels produce different outputs", () => {
    const r1 = generateReviewerBriefing(BASE_OPTS);
