import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

export interface WriteBriefingOpts {
  taskId: string;
  briefingContent: string;
}

export interface WriteBriefingResult {
  briefingPath: string;
}

/**
 * Write briefing markdown to a temporary file and return its path.
 * Creates the directory if it does not exist.
 */
export function writeBriefing(opts: WriteBriefingOpts): WriteBriefingResult {
  const { taskId, briefingContent } = opts;
  const briefingDir = join(tmpdir(), `briefing-${taskId}`);
  mkdirSync(briefingDir, { recursive: true });
  const briefingPath = join(briefingDir, "briefing.md");
  writeFileSync(briefingPath, briefingContent, "utf-8");
  return { briefingPath };
}

