      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "reviewer_claim_lost")).toBe(true);
  });
});

// ── 5. dispatched on successful claim + async submit ─────────────────────────

describe("dispatchReviewer — dispatched on success (async submit)", () => {
  it("returns dispatched and emits reviewer_submitted on successful claim and submit", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => ""); // all execSync succeed
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess()); // push succeeds

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("dispatched");
    expect(events.some((e) => e.type === "reviewer_submitted")).toBe(true);
    const submittedEvent = events.find((e) => e.type === "reviewer_submitted")!;
    expect(submittedEvent.task_id).toBe(TASK_ID);
    expect(submittedEvent.feature_id).toBe(FEATURE_ID);
    expect(submittedEvent.handle).toBe("fake-reviewer-handle");
    expect(submittedEvent.cycle).toBe(1);
  });
});

// ── 6. reviewer_started log entry written to task YAML ───────────────────────

describe("dispatchReviewer — reviewer_started log entry on success", () => {
  it("writes reviewer_started to task YAML on disk", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    await dispatchReviewer(makeDispatchOpts(wsRoot));

    const updatedTask = readTaskFromDisk(wsRoot, FEATURE_ID, TASK_ID);
    expect(updatedTask.log.some((e) => e.action === "reviewer_started")).toBe(true);
    const entry = updatedTask.log.find((e) => e.action === "reviewer_started")!;
    expect(entry.by).toBe(GIT_AUTHOR_EMAIL);
    expect(entry.at).toBeTruthy();
    expect(entry.note).toMatch(/cycle/i);
  });

  it("updates execution.last_updated_by in task YAML", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    await dispatchReviewer(makeDispatchOpts(wsRoot));

    const updatedTask = readTaskFromDisk(wsRoot, FEATURE_ID, TASK_ID);
    expect(updatedTask.execution.last_updated_by).toBe(GIT_AUTHOR_EMAIL);
  });
});

// ── 7. submitted with handleKind "review" ────────────────────────────────────

describe("dispatchReviewer — submitted with handleKind review", () => {
  it("constructs SubProcessAdapter with handleKind: 'review'", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    const { SubProcessAdapter } = await import("../src/adapters/executor/subprocess.js");
    let capturedOpts: Record<string, unknown> | null = null;
    vi.mocked(SubProcessAdapter).mockImplementationOnce((opts: Record<string, unknown>) => {
      capturedOpts = opts;
      return { submit: vi.fn().mockResolvedValue("fake-reviewer-handle") };
    });

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    const outcome = await dispatchReviewer(makeDispatchOpts(wsRoot));

    expect(outcome).toBe("dispatched");
    expect(capturedOpts).not.toBeNull();
    expect(capturedOpts!["handleKind"]).toBe("review");
  });
});

// ── 8. reviewer briefing references prUrl and resultPath ─────────────────────

describe("dispatchReviewer — briefing references prUrl and resultPath", () => {
  it("briefing content contains the PR URL", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    await dispatchReviewer(makeDispatchOpts(wsRoot));

    const briefingPath = join(tmpdir(), `briefing-reviewer-${TASK_ID}`, "briefing.md");
    const content = readFileSync(briefingPath, "utf-8");
    expect(content).toContain("https://github.com/tiendv89/agent-workflow/pull/93");
    expect(content).toContain("/review-pr");
    expect(content).toContain("terminal_status");
  });

  it("executor input resultPath uses reviewer-result prefix", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    const { SubProcessAdapter } = await import("../src/adapters/executor/subprocess.js");
    let capturedInput: ExecutorPortInput | null = null;
    vi.mocked(SubProcessAdapter).mockImplementationOnce(() => ({
      submit: vi.fn().mockImplementation(async (input: ExecutorPortInput) => {
        capturedInput = input;
        return "fake-reviewer-handle";
      }),
    }));

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    await dispatchReviewer(makeDispatchOpts(wsRoot));

    expect(capturedInput).not.toBeNull();
    expect(capturedInput!.resultPath).toMatch(/reviewer-result-T3\.json$/);
    expect(capturedInput!.resultPath).not.toMatch(/executor-result/);
  });

  it("briefing resultPath matches the executor input resultPath", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    const { SubProcessAdapter } = await import("../src/adapters/executor/subprocess.js");
    let capturedInput: ExecutorPortInput | null = null;
    vi.mocked(SubProcessAdapter).mockImplementationOnce(() => ({
      submit: vi.fn().mockImplementation(async (input: ExecutorPortInput) => {
        capturedInput = input;
        return "fake-reviewer-handle";
      }),
    }));

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    await dispatchReviewer(makeDispatchOpts(wsRoot));

    expect(capturedInput).not.toBeNull();
    const resultPath = capturedInput!.resultPath;

    const briefingPath = join(tmpdir(), `briefing-reviewer-${TASK_ID}`, "briefing.md");
    const briefingContent = readFileSync(briefingPath, "utf-8");
    expect(briefingContent).toContain(resultPath);
  });
});

