1	/**
2	 * T4: Draft-state comment resolution dispatch.
3	 *
4	 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
5	 *
6	 *   1. Claims the review work by appending a `review_started` log entry to
7	 *      the task YAML on the management-repo feature branch and pushing.
8	 *      First-push-wins: if the push is rejected, another agent claimed first.
9	 *
10	 *   2. Generates a review briefing that instructs Claude to execute the
11	 *      `respond-to-review` skill.
12	 *
13	 *   3. Invokes the Claude executor via the async SubProcessAdapter with that briefing.
14	 */
15	
16	import { execSync, spawnSync } from "node:child_process";
17	import { join } from "node:path";
18	import { tmpdir } from "node:os";
19	import { randomUUID } from "node:crypto";
20	import type { Task } from "../types/task.js";
21	import type { PrStatusResult } from "../poll/check-in-review-prs.js";
22	import { buildGitEnv } from "../git-env.js";
23	import { SubProcessAdapter } from "../adapters/executor/subprocess.js";
24	import type { ExecutorPortInput, CompletionBrokerPort } from "@workflow/runtime-abi";
25	import { taskYamlRelPath } from "../paths.js";
26	import { readTask, writeTask } from "../utils/task-yaml-io.js";
27	import { writeBriefing } from "../briefing/write-briefing.js";
28	import { preambleSection, identitySection, taskContextSection, modelSection, joinSections } from "../briefing/briefing-template.js";
29	
30	// ── Public types ──────────────────────────────────────────────────────────────
31	
32	export type DraftReviewOutcome =
33	  | "claim_lost"
34	  | "dispatched";
35	
36	export interface DispatchOneReviewOptions {
37	  workspaceRoot: string;
38	  featureId: string;
39	  taskId: string;
40	  taskBranch: string;
41	  implRepoRoot: string;
42	  /** SSH or HTTPS URL of the implementation repo. */
43	  implRepoUrl: string;
44	  gitAuthorEmail: string;
45	  gitAuthorName?: string;
46	  sshKeyPath?: string;
47	  workflowLocalPath: string;
48	  maxTurns: number;
49	  maxTokens: number;
50	  logSinkEnabled: boolean;
51	  implementationModel: string;
52	  workspaceId: string;
53	  githubToken: string;
54	  /** Completion broker for async submit. */
55	  broker: CompletionBrokerPort;
56	  /** Callback URL the runner wrapper will POST to. Pre-computed by caller. */
57	  callbackUrl: string;
58	  emit: (event: Record<string, unknown>) => void;
59	}
60	
61	export interface HandleDraftReviewsOptions {
62	  prResults: PrStatusResult[];
63	  workspaceRoot: string;
64	  resolveImplRepoRoot: (repoId: string) => string;
65	  resolveImplRepoUrl: (repoId: string) => string;
66	  resolveTaskRepoId: (featureId: string, taskId: string) => string;
67	  resolveImplementationModel: (featureId: string, taskId: string) => string;
68	  gitAuthorEmail: string;
69	  gitAuthorName?: string;
70	  sshKeyPath?: string;
71	  workflowLocalPath: string;
72	  maxTurns: number;
73	  maxTokens: number;
74	  logSinkEnabled: boolean;
75	  workspaceId: string;
76	  githubToken: string;
77	  /** Completion broker for async submit. */
78	  broker: CompletionBrokerPort;
79	  /** Callback URL the runner wrapper will POST to. */
80	  callbackUrl: string;
81	  emit: (event: Record<string, unknown>) => void;
82	}
83	
84	// ── Internal helpers ──────────────────────────────────────────────────────────
85	
86	function generateReviewBriefing(opts: {
87	  taskId: string;
88	  featureId: string;
89	  taskTitle: string;
90	  taskBranch: string;
91	  taskRepo: string;
92	  taskRepoRoot: string;
93	  workspaceRoot: string;
94	  prUrl: string;
95	  gitAuthorEmail: string;
96	  gitAuthorName: string;
97	  implementationModel: string;
98	  resultPath: string;
99	}): string {
100	  const {
101	    taskId, featureId, taskTitle, taskBranch, taskRepo, taskRepoRoot,
102	    workspaceRoot, prUrl, gitAuthorEmail, gitAuthorName, implementationModel,
103	    resultPath,
104	  } = opts;
105	
106	  return joinSections(
107	    preambleSection(),
108	    identitySection({ gitAuthorEmail, gitAuthorName }),
109	    taskContextSection("Your claimed task", {
110	      taskId, featureId, taskTitle, taskBranch,
111	      taskRepo, taskRepoRoot, workspaceRoot, prUrl,
112	    }),
113	    [
114	      "## What you must do",
115	      "",
116	      "1. Read the following documents in order to understand the task context before reviewing:",
117	      `   a. \`${workspaceRoot}/docs/features/${featureId}/product-spec.md\` — original user requirements and business constraints`,
118	      `   b. \`${workspaceRoot}/docs/features/${featureId}/technical-design.md\` — implementation approach and architecture`,
119	      `   c. \`${workspaceRoot}/docs/features/${featureId}/tasks.md\` under heading \`## ${taskId} — ${taskTitle}\` — specific task scope and subtasks`,
120	      "2. Run `/respond-to-review` to read and address all open PR review comments,",
121	      "   then convert the PR from draft back to ready-for-review.",
122	      `3. Write \`${resultPath}\` with exactly:`,
123	      `   \`{"terminal_status":"in_review","pr_url":"${prUrl}"}\``,
124	      "   This is mandatory — the runtime reads this file to confirm the review completed.",
125	      "   If you cannot complete the review, write:",
126	      `   \`{"terminal_status":"blocked","blocked_reason":"<reason>"}\` to \`${resultPath}\` instead.`,
127	      "",
128	      "Complete all steps without stopping or asking for confirmation.",
129	    ],
130	    modelSection(implementationModel),
131	    [
132	      "## Rules",
133	      "",
134	      "- Do not ask clarifying questions.",
135	      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
136	      "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
137	      `- Always write \`${resultPath}\` as the final step — even on failure.`,
138	    ],
139	  );
140	}
141	
142	// ── Public API ────────────────────────────────────────────────────────────────
143	
144	export async function dispatchOneReview(
145	  opts: DispatchOneReviewOptions,
146	): Promise<DraftReviewOutcome> {
147	  const {
148	    workspaceRoot,
149	    featureId,
150	    taskId,
151	    taskBranch,
152	    implRepoRoot,
153	    implRepoUrl,
154	    gitAuthorEmail,
155	    gitAuthorName = gitAuthorEmail,
156	    sshKeyPath,
157	    workflowLocalPath,
158	    maxTurns,
159	    maxTokens,
160	    logSinkEnabled,
161	    implementationModel,
162	    workspaceId,
163	    githubToken,
164	    broker,
165	    callbackUrl,
166	    emit,
167	  } = opts;
168	
169	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
170	  const now = new Date().toISOString();
171	
172	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
173	  try {
174	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
175	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
176	    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
177	  } catch (e) {
178	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
179	    return "claim_lost";
180	  }
181	
182	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
183	  let task: Task;
184	  try {
185	    task = readTask(workspaceRoot, featureId, taskId);
186	  } catch (e) {
187	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
188	    return "claim_lost";
189	  }
190	
191	  if (task.status !== "in_review") {
192	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: `task status is ${task.status}, expected in_review` });
193	    return "claim_lost";
194	  }
195	
196	  const lastEntry = task.log[task.log.length - 1];
197	  if (lastEntry?.action === "review_started") {
198	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
199	    return "claim_lost";
200	  }
201	
202	  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
203	  const MAX_REVIEW_CYCLES = 3;
204	  let consecutiveReviewCycles = 0;
205	  for (let i = task.log.length - 1; i >= 0; i--) {
206	    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
207	    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
208	  }
209	  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
210	    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
211	    return "claim_lost";
212	  }
213	
214	  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
215	  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
216	  task.execution.last_updated_by = gitAuthorEmail;
217	  task.execution.last_updated_at = now;
218	  writeTask(workspaceRoot, featureId, task);
219	
220	  const relPath = taskYamlRelPath(featureId, taskId);
221	  try {
222	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
223	    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
224	  } catch (e) {
225	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
226	    return "claim_lost";
227	  }
228	
229	  let claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
230	    env, encoding: "utf-8",
231	  });
232	  if (claimPush.status !== 0) {
233	    // Push rejected — another commit landed between our fetch and push.
234	    // Rebase onto origin and re-check the duplicate-claim guard before retrying.
235	    // If a competing agent actually claimed, the guard will catch it and we lose cleanly.
236	    try {
237	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
238	      execSync(`git -C "${workspaceRoot}" rebase origin/${taskBranch}`, { env, stdio: "pipe" });
239	    } catch (e) {
240	      emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: `rebase failed after push rejection: ${String(e)}` });
241	      return "claim_lost";
242	    }
243	
244	    const rebasedTask = readTask(workspaceRoot, featureId, taskId);
245	    if (rebasedTask.status !== "in_review") {
246	      emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: `task status changed to ${rebasedTask.status} during rebase` });
247	      return "claim_lost";
248	    }
249	    const rebasedLast = rebasedTask.log[rebasedTask.log.length - 1];
250	    if (rebasedLast?.action === "review_started") {
251	      emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "another agent claimed during rebase" });
252	      return "claim_lost";
253	    }
254	
255	    claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
256	      env, encoding: "utf-8",
257	    });
258	    if (claimPush.status !== 0) {
259	      emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
260	      return "claim_lost";
261	    }
262	  }
263	
264	  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });
265	
266	  // ── 4. Build review briefing and submit executor (async — T6) ────────────────
267	  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);
268	
269	  const reviewBriefing = generateReviewBriefing({
270	    taskId,
271	    featureId,
272	    taskTitle: task.title,
273	    taskBranch,
274	    taskRepo: task.repo,
275	    taskRepoRoot: implRepoRoot,
276	    workspaceRoot,
277	    prUrl: task.pr.url,
278	    gitAuthorEmail,
279	    gitAuthorName,
280	    implementationModel,
281	    resultPath,
282	  });
283	
284	  const { briefingPath } = writeBriefing({ taskId, briefingContent: reviewBriefing });
285	  const nonce = randomUUID();
286	
287	  const input: ExecutorPortInput = {
288	    taskId,
289	    featureId,
290	    workspaceId,
291	    taskRepoUrl: implRepoUrl,
292	    taskRepoBranch: taskBranch,
293	    taskRepoPath: implRepoRoot,
294	    briefingPath,
295	    resultPath,
296	    budgetTokens: maxTokens,
297	    implementationModel,
298	    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
299	    githubToken,
300	    callbackUrl,
301	    nonce,
302	  };
303	
304	  const reviewAdapter = new SubProcessAdapter({
305	    broker,
306	    extraEnv: {
307	      WORKSPACE_ROOT: workspaceRoot,
308	      TASK_BRANCH: taskBranch,
309	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
310	      GIT_AUTHOR_NAME: gitAuthorName,
311	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
312	      MAX_TURNS: String(maxTurns),
313	      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
314	    },
315	  });
316	
317	  const handle = await reviewAdapter.submit(input);
318	
319	  emit({
320	    type: "review_submitted",
321	    task_id: taskId,
322	    feature_id: featureId,
323	    handle,
324	  });
325	
326	  return "dispatched";
327	}
328	
329	export async function handleDraftReviews(
330	  opts: HandleDraftReviewsOptions,
331	): Promise<void> {
332	  const {
333	    prResults,
334	    workspaceRoot,
335	    resolveImplRepoRoot,
336	    resolveImplRepoUrl,
337	    resolveTaskRepoId,
338	    resolveImplementationModel,
339	    gitAuthorEmail,
340	    gitAuthorName,
341	    sshKeyPath,
342	    workflowLocalPath,
343	    maxTurns,
344	    maxTokens,
345	    logSinkEnabled,
346	    workspaceId,
347	    githubToken,
348	    broker,
349	    callbackUrl,
350	    emit,
351	  } = opts;
352	
353	  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);
354	
355	  for (const result of draftTasks) {
356	    const { taskId, featureId } = result;
357	
358	    let repoId: string;
359	    try {
360	      repoId = resolveTaskRepoId(featureId, taskId);
361	    } catch (e) {
362	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
363	      continue;
364	    }
365	
366	    let implRepoRoot: string;
367	    let implRepoUrl: string;
368	    try {
369	      implRepoRoot = resolveImplRepoRoot(repoId);
370	      implRepoUrl = resolveImplRepoUrl(repoId);
371	    } catch (e) {
372	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
373	      continue;
374	    }
375	
376	    let implementationModel: string;
377	    try {
378	      implementationModel = resolveImplementationModel(featureId, taskId);
379	    } catch (e) {
380	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
381	      continue;
382	    }
383	
384	    const taskBranch = `feature/${featureId}-${taskId}`;
385	
386	    try {
387	      await dispatchOneReview({
388	        workspaceRoot,
389	        featureId,
390	        taskId,
391	        taskBranch,
392	        implRepoRoot,
393	        implRepoUrl,
394	        gitAuthorEmail,
395	        gitAuthorName,
396	        sshKeyPath,
397	        workflowLocalPath,
398	        maxTurns,
399	        maxTokens,
400	        logSinkEnabled,
401	        implementationModel,
402	        workspaceId,
403	        githubToken,
404	        broker,
405	        callbackUrl,
406	        emit,
407	      });
408	    } catch (e) {
409	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
410	    }
411	  }
412	}
